"""MEMBER B. Reproducible training-data augmentation (seeded; generated by code in the notebook; never uses test text).

1. corrupt(): the corruption families the Data tab says appear in the hidden robustness subset - character insertion,
   deletion, substitution and repetition, missing/irregular spaces, random capitalisation, emojis, Unicode lookalikes,
   zero-width characters, deliberate misspellings of sensitive words, short meaningless noise strings.
   Augmented text is then passed through the SAME normaliser as test text, so the model learns what survives it.
2. noise_rows(): noise-only records (labelled 0 / NONE / 0 per the Data tab).

Used by the runner on each CV fold's TRAINING rows only (validation rows stay clean; a separate corrupted copy of the
validation rows estimates the robustness score)."""
import random
import re
import string

import numpy as np
import pandas as pd
from src.data.normalize import robust

_LOOKALIKE = {"a": "а", "e": "е", "o": "о", "p": "р", "c": "с", "y": "у", "x": "х", "i": "і", "s": "ѕ"}
_ZW = ["​", "‌", "‍", "⁠"]
_EMOJI = ["🔥", "🎁", "💰", "✅", "⚠️", "📦", "🙏", "😊", "👉", "💸"]
_SENSITIVE = {"otp": ["0tp", "o.t.p", "o t p", "oTp", "ottp"], "pin": ["p1n", "p.i.n", "piin"],
              "password": ["passw0rd", "pass word", "pasword"], "bkash": ["bkas", "b-kash", "bkassh", "bksah"],
              "nagad": ["nagadd", "n@gad", "nagd"], "click": ["clik", "cl1ck", "kllick"], "link": ["lnk", "l1nk", "linkk"],
              "parcel": ["parsel", "p@rcel", "parcell"], "prize": ["priz", "pr1ze", "prizee"], "taka": ["tk", "takaa", "tak"]}


def _noise_word(rng):
    return "".join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(5, 12)))


def corrupt(text, rng, strength=0.06):
    s = str(text)
    for word, variants in _SENSITIVE.items():
        if word in s.lower() and rng.random() < 0.5:
            idx = s.lower().find(word)
            s = s[:idx] + rng.choice(variants) + s[idx + len(word):]
    chars, out = list(s), []
    for ch in chars:
        r = rng.random()
        if r < strength * 0.25 and ch.isalpha():
            continue                                                   # deletion
        if r < strength * 0.5 and ch.isalpha():
            out.append(rng.choice(string.ascii_lowercase))            # substitution
            continue
        out.append(ch)
        if r < strength * 0.7 and ch.isalpha():
            out.append(ch)                                             # repetition
        elif r < strength * 0.85:
            out.append(rng.choice(string.ascii_lowercase))            # insertion
        elif r < strength * 0.95 and ch.lower() in _LOOKALIKE:
            out[-1] = _LOOKALIKE[ch.lower()]                           # Unicode lookalike
        elif r < strength * 1.05:
            out.append(rng.choice(_ZW))                                # zero-width character
    s = "".join(out)
    if rng.random() < 0.3:
        s = "".join(c.upper() if rng.random() < 0.3 else c for c in s)  # random capitalisation
    if rng.random() < 0.3:
        s = s.replace(" ", "", rng.randint(1, 3))                      # missing spaces
    if rng.random() < 0.2:
        s = s.replace(" ", "  ", rng.randint(1, 3))                    # irregular spaces
    if rng.random() < 0.3:
        words = s.split(" ")
        words.insert(rng.randint(0, len(words)), _noise_word(rng))     # noise string
        s = " ".join(words)
    if rng.random() < 0.3:
        s = s + " " + rng.choice(_EMOJI) if rng.random() < 0.5 else rng.choice(_EMOJI) + " " + s
    return s


def augment(frame, text_col, copies=2, strength=0.06, seed=42):
    """Return `copies` corrupted versions of every row (labels unchanged), normalised like test text."""
    if copies <= 0 or frame.empty:
        return frame.iloc[0:0]
    rng = random.Random(seed)
    parts = []
    for _ in range(copies):
        aug = frame.copy()
        raw = [corrupt(t, rng, strength) for t in frame[text_col]]
        aug[text_col] = [robust(t) for t in raw]
        if text_col + "_raw" in aug.columns:
            aug[text_col + "_raw"] = raw
        parts.append(aug)
    return pd.concat(parts, ignore_index=True)


def noise_rows(n, text_col, columns, seed=42):
    """Noise-only records: label 0, techniques NONE, action 0 (Data tab)."""
    rng = random.Random(seed + 7)
    texts = []
    for _ in range(n):
        k = rng.randint(1, 4)
        t = " ".join(_noise_word(rng) for _ in range(k))
        if rng.random() < 0.3:
            t += " " + rng.choice(_EMOJI)
        if rng.random() < 0.2:
            t = "".join(rng.choice(string.punctuation + string.digits) for _ in range(rng.randint(4, 12)))
        texts.append(robust(t))
    df = pd.DataFrame({c: 0 for c in columns if c != text_col}, index=range(n))
    df[text_col] = texts
    return df[columns] if set(columns) <= set(df.columns) else df


# ------------------------------------------------------------------ transforms of REAL rows (no new content invented)
_BANGLISH_HINT = re.compile(r"\b(apnar|apni|ami|amar|korun|koren|korte|din|diben|hobe|hoye|ase|ache|taka|bhai|vai|ki|na|ekhon|"
                            r"theke|jonno|pathan|bolen|ta|ti|e|er|kore|jan|nai|ar|o)\b", re.I)
_BENGALI = re.compile(r"[ঀ-৿]")


def to_banglish(text):
    """Bangla script -> romanised Bangla (Avro reverse transliteration); Latin parts unchanged."""
    import avro
    out = avro.reverse(text)
    return _BENGALI.sub("", out)  # drop stray combining marks avro leaves behind


def to_bangla_script(text):
    """Banglish -> Bangla script (Avro phonetic). Only for Latin text that looks like romanised Bangla."""
    import avro
    return avro.parse(text)


def transliterate_view(text):
    """The same real message in the other script, or None if it is not Bangla / Banglish."""
    t = str(text)
    if _BENGALI.search(t):
        return to_banglish(t)
    if len(_BANGLISH_HINT.findall(t)) >= 3:
        return to_bangla_script(t)
    return None


_MARKER = re.compile(r"(^|\|\|\|)\s*(\[[^\]]{1,25}\]|[A-Za-z][A-Za-z ]{0,14}:)\s*")


def register_views(text):
    """Same conversation, different surface: speaker markers removed / turns on separate lines / lower-case."""
    t = str(text)
    if "|||" not in t:
        return [t.lower()] if t != t.lower() else []
    no_markers = " ||| ".join(p.strip() for p in _MARKER.sub(r"\1", t).split("|||"))
    lines = "\n".join(p.strip() for p in t.split("|||"))
    return [v for v in {no_markers, lines, t.lower()} if v != t]


def real_row_views(frame, text_col, translit=True, views=True):
    """Extra rows that are re-renderings of real labelled rows (labels unchanged)."""
    rows = []
    for _, r in frame.iterrows():
        cands = []
        if translit:
            v = transliterate_view(r[text_col])
            if v:
                cands.append(v)
        if views:
            cands += register_views(r[text_col])
        for c in cands:
            nr = r.copy()
            nr[text_col] = robust(c)
            if text_col + "_raw" in nr.index:
                nr[text_col + "_raw"] = c
            rows.append(nr)
    return pd.DataFrame(rows, columns=frame.columns) if rows else frame.iloc[0:0]
